WITH with_windows AS (SELECT *, SUM(discount_pct) OVER (PARTITION BY MONTH(ends_on) ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_discount_pct, AVG(discount_pct) OVER w_running AS discount_pct_avg_2_prior, SUM(discount_pct) OVER w_recent AS cumulative_discount_pct, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('YEAR', starts_on), promo_code ORDER BY ends_on DESC, id) AS row_seq FROM promotions WINDOW w_running AS (PARTITION BY channel, promo_code ORDER BY discount_pct, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING), w_recent AS (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, running_discount_pct, discount_pct_avg_2_prior, cumulative_discount_pct FROM with_windows;
